import { Effect } from "effect"

export interface StockLevel {
  readonly sku: string
  readonly warehouseId: string
  readonly available: number
}

interface RestockOrder {
  readonly sku: string
  readonly warehouseId: string
  readonly quantity: number
}

export const planRestocks = (
  levels: ReadonlyArray<StockLevel>,
  target: number
) => {
  const orders: Array<RestockOrder> = []

  for (const level of levels) {
    if (level.available >= target) continue

    orders.push({
      sku: level.sku,
      warehouseId: level.warehouseId,
      quantity: target - level.available
    })
  }

  const prepareOrder = (order: RestockOrder) =>
    Effect.gen(function*() {
      yield* Effect.logInfo("Preparing restock order", {
        sku: order.sku,
        warehouseId: order.warehouseId,
        quantity: order.quantity
      })

      return {
        ...order,
        reference: `${order.warehouseId}:${order.sku}`
      }
    })

  return Effect.forEach(orders, prepareOrder, { concurrency: 4 })
}
